using namespace std;

class Solution {
public:
    int maxEqualLengthRuns(string s) {
        if (s.empty()) return 0;
        vector<int> runs;
        int cur_len = 1;
        for (int i = 1; i < (int)s.size(); i++) {
            if (s[i] == s[i - 1]) cur_len++;
            else {
                runs.push_back(cur_len);
                cur_len = 1;
            }
        }
        runs.push_back(cur_len);
        unordered_map<int, int> counts;
        int max_freq = 0;
        for (int r : runs) {
            counts[r]++;
            max_freq = max(max_freq, counts[r]);
        }
        return max_freq;
    }
};

import java.util.*;

class Solution {
    public int maxEqualLengthRuns(String s) {
        if (s.isEmpty()) return 0;
        List<Integer> runs = new ArrayList<>();
        int curLen = 1;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) == s.charAt(i - 1)) curLen++;
            else {
                runs.add(curLen);
                curLen = 1;
            }
        }
        runs.add(curLen);
        Map<Integer, Integer> counts = new HashMap<>();
        int maxFreq = 0;
        for (int r : runs) {
            counts.put(r, counts.getOrDefault(r, 0) + 1);
            maxFreq = Math.max(maxFreq, counts.get(r));
        }
        return maxFreq;
    }
}

var maxEqualLengthRuns = function(s) {
    if (!s) return 0;
    const runs = [];
    let curLen = 1;
    for (let i = 1; i < s.length; i++) {
        if (s[i] === s[i - 1]) curLen++;
        else {
            runs.push(curLen);
            curLen = 1;
        }
    }
    runs.push(curLen);
    const counts = new Map();
    let maxFreq = 0;
    for (const r of runs) {
        counts.set(r, (counts.get(r) || 0) + 1);
        maxFreq = Math.max(maxFreq, counts.get(r));
    }
    return maxFreq;
};
